import * as React from 'react';
import * as ComparisonSliderPrimitive from '@exhuma/core';
import { clsx } from 'clsx';

export interface ComparisonSliderProps extends React.ComponentPropsWithoutRef<typeof ComparisonSliderPrimitive.ComparisonSlider> {
  className?: string;
}

export const ComparisonSlider = React.forwardRef<HTMLDivElement, ComparisonSliderProps>(
  ({ className, children, ...props }, ref) => (
    <ComparisonSliderPrimitive.ComparisonSlider
      ref={ref}
      className={clsx(
        'relative overflow-hidden rounded-2xl border border-border select-none w-full max-w-2xl mx-auto',
        className
      )}
      {...props}
    >
      {children}
    </ComparisonSliderPrimitive.ComparisonSlider>
  )
);
ComparisonSlider.displayName = 'ComparisonSlider';

