import { Component, JSX, splitProps } from 'solid-js';
import * as ComparisonSliderPrimitive from '@exhuma/core';

export interface ComparisonSliderProps extends JSX.HTMLAttributes<HTMLDivElement> {
  [key: string]: unknown;
}

export const ComparisonSlider: Component<ComparisonSliderProps> = (props) => {
  const [local, others] = splitProps(props, ['class', 'children']);
  return (
    <ComparisonSliderPrimitive.ComparisonSlider
      class={`relative overflow-hidden rounded-2xl border border-border select-none w-full max-w-2xl mx-auto ${local.class ?? ''}`}
      {...others}
    >
      {local.children}
    </ComparisonSliderPrimitive.ComparisonSlider>
  );
};

