import { ComparisonSlider } from '@exhuma/core';

class ExhumaComparisonSliderElement extends HTMLElement {
  connectedCallback() {
    this.classList.add('exhuma-comparison-slider');
    this.style.display = 'block';
  }
}

if (!customElements.get('exhuma-comparison-slider')) {
  customElements.define('exhuma-comparison-slider', ExhumaComparisonSliderElement);
}

