import React from 'react';
import { View, StyleSheet, type ViewProps } from 'react-native';
import * as ComparisonSliderPrimitive from '@exhuma/core';

export interface ComparisonSliderProps extends ViewProps {
  children?: React.ReactNode;
}

export function ComparisonSlider({ style, children, ...props }: ComparisonSliderProps) {
  return (
    <View style={[styles.container, style]} {...props}>
      {children}
    </View>
  );
}

const styles = StyleSheet.create({
  container: {
    borderRadius: 16,
    borderWidth: 1,
    borderColor: '#e2e8f0',
    backgroundColor: '#ffffff',
    padding: 20,
    overflow: 'hidden',
  },
});

